-- compatibility: breaking
-- PLT04: allow a policy-configured unresolved reason to advise instead of block.
DROP TRIGGER IF EXISTS p0_close_insert_checks_guard;
DROP TRIGGER IF EXISTS rr_close_checks_transition;
DROP TRIGGER IF EXISTS rr_close_lock_checks;
CREATE TRIGGER p0_close_insert_checks_guard BEFORE INSERT ON internal_close_runs
WHEN NOT json_valid(NEW.checks_json) OR json_type(NEW.checks_json)<>'array' OR json_array_length(NEW.checks_json)<>8
 OR (SELECT count(DISTINCT json_extract(c.value,'$.code')) FROM json_each(NEW.checks_json) c
  WHERE json_extract(c.value,'$.code') IN('unposted_periodic','unapproved_drafts','subledger_control',
   'bank_reconciliation','trial_balance','report_checks','unposted_manual','fee_variance_pending'))<>8
 OR EXISTS(SELECT 1 FROM json_each(NEW.checks_json) c WHERE coalesce(json_extract(c.value,'$.status'),'') NOT IN('pass','blocked'))
 OR (NEW.status IN('preflight_passed','reviewed','locked') AND EXISTS(SELECT 1 FROM json_each(NEW.checks_json) c WHERE json_extract(c.value,'$.status')<>'pass'))
 OR (NEW.status='preflight_failed' AND NOT EXISTS(SELECT 1 FROM json_each(NEW.checks_json) c WHERE json_extract(c.value,'$.status')='blocked'))
 OR NOT EXISTS(SELECT 1 FROM json_each(NEW.checks_json) j WHERE json_extract(j.value,'$.code')='fee_variance_pending' AND json_extract(j.value,'$.status')=CASE WHEN (EXISTS(SELECT 1 FROM fee_receivable_variances v JOIN books b ON b.id=v.book_id WHERE v.book_id=NEW.book_id AND v.period=b.period AND v.status='pending') AND NOT EXISTS(SELECT 1 FROM accounting_policies p JOIN ledger_periods lp ON lp.ledger_id=p.ledger_id WHERE lp.book_id=NEW.book_id AND p.status='active' AND p.effective_from<=(SELECT period FROM books b2 WHERE b2.id=NEW.book_id) AND (p.effective_to IS NULL OR p.effective_to>=(SELECT period FROM books b2 WHERE b2.id=NEW.book_id)) AND EXISTS(SELECT 1 FROM json_each(p.fee_variance_reasons_json) r WHERE json_extract(r.value,'$.code')='unresolved' AND json_extract(r.value,'$.blocks_close')=0))) THEN 'blocked' ELSE 'pass' END) OR NOT EXISTS(SELECT 1 FROM json_each(NEW.checks_json) j WHERE json_extract(j.value,'$.code')='unposted_manual' AND json_extract(j.value,'$.status')=CASE WHEN EXISTS(SELECT 1 FROM manual_review_requests m WHERE m.book_id=NEW.book_id AND NOT EXISTS(SELECT 1 FROM manual_review_withdrawals w WHERE w.request_id=m.id) AND NOT EXISTS(SELECT 1 FROM vouchers v JOIN voucher_review_completions c ON c.id=v.id WHERE v.review_request_id=m.id)) THEN 'blocked' ELSE 'pass' END)
BEGIN SELECT RAISE(ABORT,'Close preflight checks must be complete and consistent'); END;
CREATE TRIGGER rr_close_checks_transition BEFORE UPDATE ON internal_close_runs WHEN NEW.status IN('reviewed','locked') AND OLD.status<>NEW.status AND (NOT json_valid(NEW.checks_json) OR json_type(NEW.checks_json)<>'array' OR json_array_length(NEW.checks_json)<>8
 OR (SELECT count(DISTINCT json_extract(c.value,'$.code')) FROM json_each(NEW.checks_json) c
  WHERE json_extract(c.value,'$.code') IN('unposted_periodic','unapproved_drafts','subledger_control',
   'bank_reconciliation','trial_balance','report_checks','unposted_manual','fee_variance_pending'))<>8
 OR EXISTS(SELECT 1 FROM json_each(NEW.checks_json) c WHERE coalesce(json_extract(c.value,'$.status'),'') NOT IN('pass','blocked'))
 OR (NEW.status IN('preflight_passed','reviewed','locked') AND EXISTS(SELECT 1 FROM json_each(NEW.checks_json) c WHERE json_extract(c.value,'$.status')<>'pass'))
 OR (NEW.status='preflight_failed' AND NOT EXISTS(SELECT 1 FROM json_each(NEW.checks_json) c WHERE json_extract(c.value,'$.status')='blocked'))
 OR NOT EXISTS(SELECT 1 FROM json_each(NEW.checks_json) j WHERE json_extract(j.value,'$.code')='fee_variance_pending' AND json_extract(j.value,'$.status')=CASE WHEN (EXISTS(SELECT 1 FROM fee_receivable_variances v WHERE v.book_id=NEW.book_id AND v.period=(SELECT period FROM internal_close_runs r WHERE r.id=NEW.id) AND v.status='pending') AND NOT EXISTS(SELECT 1 FROM accounting_policies p JOIN ledger_periods lp ON lp.ledger_id=p.ledger_id WHERE lp.book_id=NEW.book_id AND p.status='active' AND p.effective_from<=(SELECT period FROM internal_close_runs r WHERE r.id=NEW.id) AND (p.effective_to IS NULL OR p.effective_to>=(SELECT period FROM internal_close_runs r WHERE r.id=NEW.id)) AND EXISTS(SELECT 1 FROM json_each(p.fee_variance_reasons_json) r WHERE json_extract(r.value,'$.code')='unresolved' AND json_extract(r.value,'$.blocks_close')=0))) THEN 'blocked' ELSE 'pass' END) OR NOT EXISTS(SELECT 1 FROM json_each(NEW.checks_json) j WHERE json_extract(j.value,'$.code')='unposted_manual' AND json_extract(j.value,'$.status')=CASE WHEN EXISTS(SELECT 1 FROM manual_review_requests m WHERE m.book_id=NEW.book_id AND NOT EXISTS(SELECT 1 FROM manual_review_withdrawals w WHERE w.request_id=m.id) AND NOT EXISTS(SELECT 1 FROM vouchers v JOIN voucher_review_completions c ON c.id=v.id WHERE v.review_request_id=m.id)) THEN 'blocked' ELSE 'pass' END)) BEGIN SELECT RAISE(ABORT,'Close preflight checks must be complete and consistent'); END;
CREATE TRIGGER rr_close_lock_checks BEFORE INSERT ON internal_period_locks WHEN NOT EXISTS(SELECT 1 FROM internal_close_runs r WHERE r.id=NEW.close_run_id AND r.book_id=NEW.book_id AND NOT(NOT json_valid(r.checks_json) OR json_type(r.checks_json)<>'array' OR json_array_length(r.checks_json)<>8
 OR (SELECT count(DISTINCT json_extract(c.value,'$.code')) FROM json_each(r.checks_json) c
  WHERE json_extract(c.value,'$.code') IN('unposted_periodic','unapproved_drafts','subledger_control',
   'bank_reconciliation','trial_balance','report_checks','unposted_manual','fee_variance_pending'))<>8
 OR EXISTS(SELECT 1 FROM json_each(r.checks_json) c WHERE coalesce(json_extract(c.value,'$.status'),'') NOT IN('pass','blocked'))
 OR (r.status IN('preflight_passed','reviewed','locked') AND EXISTS(SELECT 1 FROM json_each(r.checks_json) c WHERE json_extract(c.value,'$.status')<>'pass'))
 OR (r.status='preflight_failed' AND NOT EXISTS(SELECT 1 FROM json_each(r.checks_json) c WHERE json_extract(c.value,'$.status')='blocked'))
 OR NOT EXISTS(SELECT 1 FROM json_each(r.checks_json) j WHERE json_extract(j.value,'$.code')='fee_variance_pending' AND json_extract(j.value,'$.status')=CASE WHEN (EXISTS(SELECT 1 FROM fee_receivable_variances v WHERE v.book_id=r.book_id AND v.period=r.period AND v.status='pending') AND NOT EXISTS(SELECT 1 FROM accounting_policies p JOIN ledger_periods lp ON lp.ledger_id=p.ledger_id WHERE lp.book_id=r.book_id AND p.status='active' AND p.effective_from<=r.period AND (p.effective_to IS NULL OR p.effective_to>=r.period) AND EXISTS(SELECT 1 FROM json_each(p.fee_variance_reasons_json) x WHERE json_extract(x.value,'$.code')='unresolved' AND json_extract(x.value,'$.blocks_close')=0))) THEN 'blocked' ELSE 'pass' END) OR NOT EXISTS(SELECT 1 FROM json_each(r.checks_json) j WHERE json_extract(j.value,'$.code')='unposted_manual' AND json_extract(j.value,'$.status')=CASE WHEN EXISTS(SELECT 1 FROM manual_review_requests m WHERE m.book_id=r.book_id AND NOT EXISTS(SELECT 1 FROM manual_review_withdrawals w WHERE w.request_id=m.id) AND NOT EXISTS(SELECT 1 FROM vouchers v JOIN voucher_review_completions c ON c.id=v.id WHERE v.review_request_id=m.id)) THEN 'blocked' ELSE 'pass' END))) BEGIN SELECT RAISE(ABORT,'Close preflight checks must be complete and consistent'); END;
